{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Bumetanide, which shares the sulfonamide, carboxylic acid, secondary amine, and aromatic substituents of the query, has absolute oral bioavailability of about 80% in humans (transfer 0.9916), strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Probenecid, a sulfonamide-containing carboxylic acid, is essentially completely absorbed orally with ~100% bioavailability in humans (transfer 0.993), showing that this acidic polar class can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Para-aminosalicylic acid, an aminobenzoic acid with a phenol, has 50–60% oral bioavailability in humans (transfer 0.993), supporting high F for the query's ionizable aromatic acid/amine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Bromfenac, an aminoarylacetic acid, has 67% absolute oral bioavailability under fasting conditions in healthy subjects (transfer 0.9927), directly matching the fasted condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Safinamide, a polar amine/amide drug, has 95% absolute oral bioavailability in the fasted state (transfer 0.9928), demonstrating that polar and ionizable groups do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Rigosertib, which contains carboxylic acid and sulfonamide-like polar groups, has 34.8% absolute oral bioavailability in fasting patients (transfer 0.9919), still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Despite the unfavorable physicochemical prior, multiple high-transfer human absolute bioavailability measurements for close structural analogues (bumetanide, probenecid, PAS, bromfenac, safinamide, rigosertib) all exceed 20%, often substantially; therefore predict high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule.",
    "The query's furfurylamino substituent is not represented in the analogues; possible metabolic or transporter effects specific to this group are unmeasured.",
    "Most analogue data are from healthy subjects or patients; disease-state or formulation effects for the query are unknown.",
    "Fasted-state data are available for several analogues, but not all; fed-state differences are not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

